function grammar(title: string, meaning: string, form: string, ex: string, exUz: string, wrong: string, right: string, domain = "education"): any {
  const pool = DOMAIN_EXAMPLES[domain] ?? DOMAIN_EXAMPLES.education;
  const examples = [{ en: ex, uz: exUz }, ...pool.filter((x) => x.en !== ex).slice(0, 2)];
  return {
    title, titleUz: title, meaning, meaningUz: meaning, form, formUz: form, why: meaning, whyUz: meaning,
    examples,
    negative: { form: `Negative/contrast form: ${form}`, examples: [{ en: pool[0]!.en, uz: pool[0]!.uz }] },
    question: { form: `Question pattern: ${form}`, examples: [{ en: `Why does this structure fit the context?`, uz: `Nima uchun bu tuzilma ushbu kontekstga mos keladi?` }] },
    mistakes: [{ wrong, right, why: meaning, whyUz: meaning }, { wrong, right, why: `Check the form and the time reference.`, whyUz: `Shakl va vaqt ma’nosini tekshiring.` }],
  };
}

