    society: ["local community", "reduce inequality", "public policy", "private citizen", "migration patterns", "affordable housing", "public services", "political debate", "social welfare", "equal access", "equal opportunity", "social impact"],
    environment: ["reduce emissions", "renewable energy", "nature conservation", "global climate", "natural resources", "household waste", "sustainable development", "natural habitat", "severe drought", "protect biodiversity", "environmental impact", "carbon footprint"],
